import type { TMessage, TOnMessage, TTab } from '../../../../src'

import { useCallback, useEffect, useRef, useState } from 'react'

import { Chat } from '../../../../src'
import { getNewMessage } from '../lib/getNewMessage'
import { handleAIResponse } from '../lib/handleAIResponse'
import { messages3 } from '../lib/messages3'
import { messagesAI } from '../lib/messagesAI'
import { messagesWithRole } from '../lib/messagesWithRole'

const itemsTab = [
    {
        value: 'supplier',
        label: 'Поставщик',
    },
    {
        value: 'employee',
        label: 'Сотрудник банка',
    },
    {
        value: 'ai',
        label: 'AI агент',
    },
] satisfies Omit<TTab, 'content'>[]

const initialMessages = {
    supplier: messagesWithRole,
    employee: messages3,
    ai: messagesAI,
}

export const ChatTabsDemo = () => {
    const [selectedTabId, setSelectedTabId] = useState<string>('')
    const [isLoadingTabs, setIsLoadingTabs] = useState<boolean>(true)
    const [messagesByTab, setMessagesByTab] = useState<Record<string, TMessage[]>>(initialMessages)
    const [tapItems, setTabItems] = useState<Omit<TTab, 'content'>[]>()

    const [isTabSwitching, setIsTabSwitching] = useState(false)

    const [isLoadingByTab, setIsLoadingByTab] = useState<Record<string, boolean>>({
        supplier: false,
        employee: false,
        ai: false,
    })

    const lastUserMessageIdByTab = useRef<Record<string, string | null>>({
        supplier: null,
        ai: null,
    })

    const currentMessages = messagesByTab[selectedTabId] || []
    const currentIsLoading = isLoadingByTab[selectedTabId] || false

    const onChangeIsRead = useCallback(
        (messagesToUpdate: TMessage[] | undefined) => {
            if (!messagesToUpdate || messagesToUpdate.length === 0) return
            const messageIdsToUpdate = new Set(messagesToUpdate.map((msg) => msg.id))
            setMessagesByTab((prev) => {
                return {
                    ...prev,
                    [selectedTabId]: prev[selectedTabId].map((msg) =>
                        messageIdsToUpdate.has(msg.id) && !msg.isRead ? { ...msg, isRead: true } : msg
                    ),
                }
            })
        },
        [selectedTabId]
    )

    const onTabChange = useCallback(async (newTabId: string) => {
        // Запуск имитации загрузки при переключении таба
        setIsTabSwitching(true)
        await new Promise((resolve) => setTimeout(resolve, 500))
        setIsTabSwitching(false)

        setSelectedTabId(newTabId)
    }, [])

    const handleMessage: TOnMessage = async (value, files, repliedMessage) => {
        const userMessage = getNewMessage(value, files, true, repliedMessage)

        setMessagesByTab((prev) => ({
            ...prev,
            [selectedTabId]: [...(prev[selectedTabId] || []), userMessage],
        }))

        if (selectedTabId !== 'employee') {
            lastUserMessageIdByTab.current[selectedTabId] = userMessage.id

            setIsLoadingByTab((prev) => ({
                ...prev,
                [selectedTabId]: true,
            }))

            // Запускаем AI ответ для текущего таба
            await handleAIResponse({
                setMessages: (newMessagesSetter) => {
                    setMessagesByTab((prev) => {
                        const currentTabMessages = prev[selectedTabId] || []
                        const newMessages =
                            typeof newMessagesSetter === 'function'
                                ? newMessagesSetter(currentTabMessages)
                                : newMessagesSetter

                        return {
                            ...prev,
                            [selectedTabId]: newMessages,
                        }
                    })
                },
                lastUserMessageIdRef: { current: userMessage.id },
            })

            setIsLoadingByTab((prev) => ({
                ...prev,
                [selectedTabId]: false,
            }))
        }
    }

    ///имитация запроса табов с сервера
    useEffect(() => {
        setTimeout(() => {
            setTabItems(itemsTab)
            setSelectedTabId(itemsTab[0].value)
            setIsLoadingTabs(false)
        }, 500)
    }, [])

    return (
        <Chat
            attachVisible
            isLoadingContent={isTabSwitching || currentMessages.length === 0}
            isLoadingTabs={isLoadingTabs}
            messages={currentMessages}
            tabOptions={{
                items: tapItems || [],
                onChange: onTabChange,
                value: selectedTabId,
            }}
            title="Чат с табами"
            typing={currentIsLoading ? [{ role: 'AI' }] : undefined}
            onChangeIsRead={onChangeIsRead}
            onMessage={handleMessage}
        />
    )
}

