import { SplitContainer, Paper, Page, useGlobalBulkActions, FlexBox } from '../../../../../src'

const pageActions = {
    buttonItems: [
        {
            label: 'Отказать',
            value: 'deny',
            onClick: () => console.info('deny'),
        },
        {
            label: 'Отправить в банк',
