            master={
                <Page
                    content={
                        <Paper height="500px" overflow="scroll">
                            <FlexBox height="120%">
                                <H5>Master - на скролл здесь GlobalBulkActions не реагирует</H5>
                            </FlexBox>
                        </Paper>
                    }
                />
            }
        />
    )
}

