                message: 'Длинное ДлинноеДлинноеДлинноеДлинное Длинное Длинное сообщение',
                semantic: 'E',
            },
            {
                message: 'Короткое сообщение',
            },
        ],
    }

    const buttonsList = [
        {
            label: 'Отказать',
            value: 'btn-1',
            onClick: () => {},
        },
        {
            label: 'Отправить в банк',
            value: 'btn-3',
            onClick: () => showToasts({ messages: [messages[3]] }),
            isMain: true,
        },
    ]
    const messages = getMessagesFromResponse(response).filter(({ target }) => !target)

    useEffect(() => {
        setGlobalParam({
            buttonItems: buttonsList,
        })
