import type { TUseWizardHandleSubmit, TWizardItem } from '../../../../src'
import type { FieldValues } from 'react-hook-form'

import type { ComponentProps } from 'react'

import { BodyM, Breadcrumbs } from '@salutejs/sdds-cs'
import { useEffect, useState } from 'react'
import { FormProvider, useForm } from 'react-hook-form'

import { FlexBox, MutationCheckbox, SplitContainer } from '../../../../src'
import { WizardPage } from '../../../../src/pages/WizardPage/WizardPage'
import { wizardData } from '../lib/wizardData'

/** Шаги с формой. */
const WITH_FORM_STEP_VALUES = ['2', 'equipment-5', 'tech-5']

/** Какая-то компонента с любой формой. */
const StepCheckbox = ({ label, value }: { value: string; label: string }) => {
    return <MutationCheckbox item={{ label }} label={label} name={value} options={{ required: 'Обязательное поле' }} />
}

/**
 * К каждому шагу есть своя компонента - делаем map для удобства.
 * Компонента с формой используется одна - это для удобства, в реальности могут быть разные.
 */
const contentMap: Record<string, TWizardItem['content']> = {
    '1': (
        <FlexBox height="70vh">
            <BodyM>Контент шага 1: начальный экран</BodyM>
        </FlexBox>
    ),
    '2': <StepCheckbox label="Подтвердить" value="2" />,
    'equipment-4': <BodyM>Контент шага оборудования 4: детали</BodyM>,
    'equipment-5': <StepCheckbox label="Закупить оборудование" value="equipment-5" />,
    'tech-4': <BodyM>Контент шага техники 4: детали</BodyM>,
    'tech-5': <StepCheckbox label="Закупить технику" value="tech-5" />,
    final: <BodyM>Контент шага общего завершающего шага</BodyM>,
}
/**
 * Подставляем content для каждого шага.
 * Вместо contentMap можно использовать Outlet, но тогда маппинг надо делать внутри WizardPageDemo и управлять состоянием value придётся самостоятельно.
 */
export const items: TWizardItem[] = wizardData.map((item) => ({
    ...item,
    content: item.content || contentMap[item.value],
    // content: item.content || <Outlet>,
}))

//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

export const argsWizardPage: ComponentProps<typeof WizardPage> = {
    title: 'Заголовок WizardPage',
    textFinish: 'Завершить закупку',
    value: [wizardData[0].value],
    onFinish: () => console.info('Finish'),
    items: items,
    onChange: () => {},
}

export const WizardPageDemo = (args: ComponentProps<typeof WizardPage>) => {
    const [isLoading, setIsLoading] = useState(false)
    const defaultStepValue = wizardData[0].value
    const [value, setValue] = useState<string[]>([defaultStepValue])
    const currentStepValue = value.at(-1) || defaultStepValue
    const isStepWithForm = WITH_FORM_STEP_VALUES.includes(currentStepValue)

    const form = useForm()

    const handleChange = (newValue: string[]) => {
        setValue(newValue)
    }

    const handleSubmit = isStepWithForm ? (form.handleSubmit as unknown as TUseWizardHandleSubmit) : undefined

    const onSubmit = (data: FieldValues, newValue: string[]) => {
        setIsLoading(true)
        console.info('Имитация отправки формы: ', { newValue, data })
        setTimeout(() => {
            // Не забываем установить value.
            // При указании handleSubmit, onChange и onContinue не отрабатывают автоматически, чтобы была возможность сделать клиентскую и серверную валидацию формы.
            handleChange(newValue)
            setIsLoading(false)
        }, 1000)
    }

    useEffect(() => {
        // Если текущий шаг содержит форму, то устанавливаем нужные значения на каждое изменение currentStepValue.
        if (isStepWithForm) {
            const newFormValues = { [currentStepValue]: false }
            form.reset(newFormValues)
        }
    }, [currentStepValue])

    return (
        <SplitContainer
            master={
                <FormProvider {...form}>
                    <WizardPage
                        breadcrumbs={
                            <Breadcrumbs
                                items={[{ title: 'Реестр документов', href: '/' }, { title: 'Документ' }]}
                                size="s"
                            />
                        }
                        handleSubmit={handleSubmit?.(onSubmit)}
                        isLoading={isLoading}
                        {...args}
                        items={args.items}
                        textFinish={args.textFinish}
                        title={args.title}
                        value={value}
                        onChange={handleChange}
                        onFinish={() => console.info('Finish')}
                    />
                </FormProvider>
            }
        />
    )
}

