 * Вместо contentMap можно использовать Outlet, но тогда маппинг надо делать внутри WizardPageDemo и управлять состоянием value придётся самостоятельно.
 */
const itemsWizard2: TWizardItem[] = wizardData.map((item) => ({
    ...item,
    content: item.content || contentSimpleMap[item.value],
    // content: item.content || <Outlet>,
}))

const progressBarItems: TProgressBarWizardProps['items'] = [
    { value: '1', textTooltip: 'Первый шаг' },
    { value: '2', textTooltip: 'Второй шаг' },
    { value: '3', textTooltip: 'Третий шаг' },
    { value: ['details', 'confirmation'], textTooltip: 'Группа этапов 4-го шага' },
    { value: 'final', textTooltip: 'Финальный шаг' },
]

/** Маппинг шагов визарда в ProgressBar */
const progressBarStepMap: Record<string, string> = {
    '1': '1',
    '2': '2',
    '3': '3',
    'equipment-4': 'details',
    'tech-4': 'details',
    'equipment-5': 'confirmation',
    'tech-5': 'confirmation',
    final: 'final',
}

//////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////////

export const argsWizardPageProgressBar: ComponentProps<typeof WizardPage> = {
    title: 'Заголовок WizardPage',
    textFinish: 'Завершить закупку',
    value: [wizardData[0].value],
    onFinish: () => console.info('Finish'),
    items: itemsWizard2,
    progressBar: {
        value: [],
        items: progressBarItems,
    },
    onChange: () => {},
    onEdit: () => {
        console.info('Click edit')
    },
}

export const WizardPageProgressBarDemo = (args: ComponentProps<typeof WizardPage>) => {
    const [isLoading, setIsLoading] = useState(false)
    const defaultStepValue = wizardData[0].value
    const [value, setValue] = useState<string[]>([defaultStepValue])
    const [progressValue, setProgressValue] = useState<string[]>(args?.progressBar?.value || [])

    const handleChange = (newValue: string[]) => {
        setIsLoading(true)
        // Для имитации запросов с сервера
        setTimeout(() => {
            setValue(newValue)
            setIsLoading(false)
        }, 1000)

        // Установка value для progressBar
        const completedSteps = newValue.slice(0, -1)
        setProgressValue(completedSteps.map((v) => progressBarStepMap[v] ?? '').filter(Boolean))
    }

    return (
        <SplitContainer
            master={
                <WizardPage
                    breadcrumbs={
                        <Breadcrumbs
                            items={[{ title: 'Реестр документов', href: '/' }, { title: 'Документ' }]}
                            size="s"
                        />
                    }
                    isLoading={isLoading}
                    {...args}
                    progressBar={{
                        value: progressValue,
                        items: args.progressBar?.items || progressBarItems,
                    }}
                    value={value}
                    onChange={handleChange}
                />
            }
        />
    )
}

