import { IconTrashOutline } from '@salutejs/plasma-icons'
import { BodyM, Button, H3 } from '@salutejs/sdds-cs'
import { useState } from 'react'

import { FlexBox, Modal, MobileModal, Paper, TaskModal, useConfirm, useGlobalBulkActions } from '../../../src'
import { Content } from '../../components/Modal/Modal/ui/Content'

const modalFooter = (onClose: () => void) => (
    <>
        <Button size="s" view="clear" onClick={onClose}>
            Третье
        </Button>
        <Button size="s" view="secondary" onClick={onClose}>
            Второстепенное действие
        </Button>
        <Button size="s" view="accent" onClick={onClose}>
            Действие
        </Button>
    </>
)

export const ModalsDemo = () => {
    const [isModalOpen, setIsModalOpen] = useState(false)
    const [isMobileModalOpen, setIsMobileModalOpen] = useState(false)
    const [isTaskModalOpen, setIsTaskModalOpen] = useState(false)

    const confirm = useConfirm()
    const { showToasts } = useGlobalBulkActions()
    const handleConfirm = async () => {
        const answer = await confirm({
            Icon: IconTrashOutline,
            title: 'Удаление архива',
            message: 'После очистки весь реестр станет пустым',
            cancelText: 'Отменить',
            confirmText: 'Удалить',
        })
        showToasts([{ text: answer ? 'Архив удалён' : 'Отмена удаления' }])
    }

    return (
        <FlexBox flexDirection="column" gap={4} height="100%">
            <Paper flexDirection="column" gap={3}>
                <H3>Модальные окна</H3>
                <FlexBox gap={2}>
                    <Button text="Modal" view="accent" onClick={() => setIsModalOpen(true)} />
                    <Button text="MobileModal" view="secondary" onClick={() => setIsMobileModalOpen(true)} />
                    <Button text="TaskModal" view="secondary" onClick={() => setIsTaskModalOpen(true)} />
                    <Button text="Confirm (useConfirm)" view="secondary" onClick={handleConfirm} />
                    <Button
                        text="showToast"
                        view="clear"
                        onClick={() => showToasts([{ text: 'Сообщение показано' }])}
                    />
                </FlexBox>

                <Modal
                    content={<Content />}
                    footer={modalFooter(() => setIsModalOpen(false))}
                    opened={isModalOpen}
                    size="m"
                    title="Заголовок модального окна"
                    onClose={() => setIsModalOpen(false)}
                />
                <MobileModal
                    content={<Content />}
                    footer={modalFooter(() => setIsMobileModalOpen(false))}
                    opened={isMobileModalOpen}
                    title="Заголовок мобильного окна"
                    onClose={() => setIsMobileModalOpen(false)}
                />
                <TaskModal
                    actions={{
                        main: { text: 'Согласовать', onClick: () => console.info('Согласовать') },
                        secondary: { text: 'Перенести', onClick: () => console.info('Перенести') },
                        clear: { text: 'Отказаться', onClick: () => console.info('Отказаться') },
                    }}
                    content={<BodyM>Контент задачи</BodyM>}
                    headerDetail={[
                        { label: 'Номер задачи', value: 'TSK-2026-0001' },
                        { label: 'Создана', value: '10.08.2026' },
                    ]}
                    opened={isTaskModalOpen}
                    task={{
                        title: 'Задача по согласованию договора',
                        description: 'Согласуйте договор с контрагентом до конца квартала',
                        type: 'Согласование',
                        typeColor: 'skyBlue',
                        status: 'В работе',
                        statusColor: 'attention',
                        priority: 1,
                    }}
