import type { TTableOptions } from '../../../src'
import type { TDeliveryRegistry } from '../lib/types'

import { IconTrashOutline } from '@salutejs/plasma-icons'

import { Table, useTable, useConfirm, useGlobalBulkActions } from '../../../src'
import { columnsDemo, dataDemo } from '../lib'
import { MDeliveryRegistry } from '../lib/types'

export const tableArgs: TTableOptions<TDeliveryRegistry> = {
    columns: columnsDemo,
    data: dataDemo,
    meta: MDeliveryRegistry,
    enableTopToolbarActionsTooltip: true,
}

export const ConfirmWithTableDemo = (tableArgs: TTableOptions<TDeliveryRegistry>) => {
    const confirm = useConfirm()
    const { showToasts } = useGlobalBulkActions()
    const table = useTable<TDeliveryRegistry>({
        ...tableArgs,
        rowActions: [
            ...(tableArgs.rowActions ?? []),
            {
                label: 'удаление',
                icon: 'delete',
                visibleAccessorKey: 'actionControl.createEdo',
                onClick: async () => {
                    const answer = await confirm({
                        Icon: IconTrashOutline,
                        title: 'Удаление ряда',
                        message: 'Вы уверены, что хотите удалить ряд?',
                        cancelText: 'Отменить',
                        confirmText: 'Удалить',
                        portal: table.options.state.isFullScreen ? table.refs.mainContainerRef : undefined,
                    })
                    showToasts([{ text: answer ? 'Ряд удалён' : 'Отмена удаления' }])
                },
            },
        ],
    })

    return <Table table={table} />
}

