import type { TTableOptions } from '../../../src'
import type { TDeliveryRegistryExtended } from '../lib/types'

import { Button } from '@salutejs/sdds-cs'
import { useState } from 'react'
import { FormProvider, useForm } from 'react-hook-form'

import { Table, useTable } from '../../../src'
import { Box } from '../../../src/layouts/Box'
import { editColumnsDemo, editDataDemo } from '../lib'
import { MDeliveryRegistry } from '../lib/types'

export const tableArgs: TTableOptions<TDeliveryRegistryExtended> = {
    columns: editColumnsDemo,
    data: editDataDemo.map((item) => ({
        ...item,
        id: [item.id.toString()],
    })),
    meta: MDeliveryRegistry,
    name: 'data',
    enableRowNumbers: true,
    enableEditing: true,
    enableCreating: true,
    enableDeleting: true,
    initialState: { isEditing: true },
}

export const EditTableDemo = (tableArgs: TTableOptions<TDeliveryRegistryExtended>) => {
    // Имитирует внешнее хранилище данных
    const [savedData, setSavedData] = useState(structuredClone(tableArgs.data ?? []))

    const form = useForm({
        defaultValues: { data: savedData },
    })

    const formData = form.watch('data')

    const table = useTable<TDeliveryRegistryExtended>({
        footerRender: (props) => {
            return (
                <Box display="flex" gap={1} justifyContent="flex-end">
                    <Button
                        text="Отменить"
                        view="clear"
                        onClick={() => {
                            // Имитирует взятие старых данных
                            form.reset({ data: savedData })
                            props.setIsEditing(false)
                        }}
                    />
                    <Button
                        text="Сохранить"
                        onClick={form.handleSubmit(
                            (formData) => {
                                // Имитирует отправку данных на сервер
                                setSavedData(structuredClone(formData.data))
                                props.setIsEditing(false)
                            },
                            () => {
                                // showToast removed — not needed in story
                            }
                        )}
                    />
                </Box>
            )
        },
        ...tableArgs,
        data: formData,
    })

    return (
        <FormProvider {...form}>
            <Table table={table} />
        </FormProvider>
    )
}

