                            props.setIsEditing(false)
                        }}
                    />
                    <Button
                        text="Сохранить"
                        onClick={form.handleSubmit(
                            (formData) => {
                                // Имитирует отправку данных на сервер
                                setSavedData(structuredClone(formData.data))
                                props.setIsEditing(false)
                            },
                            () => showToasts([{ text: 'Исправьте ошибки', view: 'negative' }])
