export const TableInModalDemo = (tableArgs: TTableOptions<TDeliveryRegistry>) => {
    const [isOpen, setIsOpen] = useState(true)
    const modalRef = useRef<HTMLDivElement | null>(null)

    const table = useTable<TDeliveryRegistry>({
        portal: modalRef,
        ...tableArgs,
    })

    return (
        <FlexBox>
            <Button size="s" text="open modal" view="accent" onClick={() => setIsOpen(!isOpen)} />
            <Modal
                ref={modalRef}
                content={<Table table={table} />}
                opened={isOpen}
                size="fs"
                title="Большой заголовок "
                onClose={() => setIsOpen(false)}
            />
        </FlexBox>
    )
}

