export const WidgetPieDemo = <WidgetItem extends TPieItem>({
    data,
    ...rest
}: ComponentProps<typeof WidgetPie<WidgetItem>>) => {
    const [date, setDate] = useState<Date>(new Date('2025-05-21'))
    const [newData, setNewData] = useState(data)
    useEffect(() => {
