                                setNewData(
                                    newData.map((item) => ({
                                        ...item,
                                        value: Math.floor(Math.random() * 35 + 5),
                                    }))
                                )
                            }}
                        />
                    }
                    centeredMetricPostfix="шт."
                    centeredMetricPostfixVisible={true}
                    data={newData}
                    getHref={(item) => `/?${item.id}`}
                    href="/my-app1"
                    legendItemCountVisible={false}
                    legendTitle="Легенда в шт."
                    navigate={console.info}
                    {...rest}
                />
            </Box>
            <Box height="260px" position="relative" width="524px">
                <WidgetPie
                    actions={
                        <SimpleDatePicker
                            value={date}
